function productDefaults(){defaults({player:'玩家 A',wrong:[],reviewMode:false,observedIndex:-1})}
function productRender(){if(state.feedback&&!state.feedback.correct&&p.observedIndex!==state.index){const q=state.questions[state.index];if(q&&!p.wrong.some(x=>x.name===q.name))p.wrong.push(clone(q));p.observedIndex=state.index}if(!state.feedback)p.observedIndex=-1;put(`<div class="grid"><div>${box('练习模式',`<form id="player" class="fields">${field('玩家代号','player','text',p.player,'required maxlength="20"')}<button>保存代号</button></form><div class="row" style="margin-top:15px">${btn('打乱题目重新开始','shuffle','')}${btn('只练错题','wrong-mode','')}</div>${note('重新开始会清空当前未完成的分数，已完成成绩保留。')}`)}${box('错题再想一遍',rows(p.wrong,x=>`<div class="item"><div><strong>${esc(x.name)}</strong><p>${esc(x.bin)} · ${esc(x.reason)}</p></div><button data-mastered="${esc(x.name)}" class="small">已理解，移出</button></div>`))}</div><div>${box('自编题管理',rows(state.custom,(x,i)=>`<div class="item"><div>${esc(x.name)}<p>${esc(x.bin)} · ${esc(x.reason)}</p></div><button data-remove="${i}" class="small">删除</button></div>`)+note('上方新增题目会进入自编题库；删除后下轮生效。'))}${box('全家成绩记录',rows(state.board,x=>`<div class="item"><span>${esc(x.player||'家庭练习')} · 第 ${x.round} 轮</span><b>${x.score}/${x.max}</b></div>`)+btn('导出成绩 CSV','scores-csv',''))}</div></div>`);form('player',v=>{p.player=v.player;commit()});const restart=list=>{state.questions=clone(list);state.index=0;state.score=0;state.feedback=null;p.observedIndex=-1;commit()};on('shuffle',()=>{const qs=[...clone(seed.questions),...clone(state.custom)];for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}p.reviewMode=false;restart(qs)});on('wrong-mode',()=>{if(!p.wrong.length)return toast('目前没有错题');p.reviewMode=true;restart(p.wrong)});deleteButtons('mastered',name=>{p.wrong=p.wrong.filter(x=>x.name!==name);commit()});deleteButtons('remove',i=>{state.custom.splice(+i,1);commit()});on('scores-csv',()=>exportCSV('分类成绩.csv',['玩家','轮次','得分','总分'],state.board.map(x=>[x.player||'家庭练习',x.round,x.score,x.max])))}
